import React from 'react';
import member from '../../../assets/member.png';
import President from '../../../assets/president.png';

const hierarchy = {
  president: { title: 'President', name: 'Mr. XYZ Patel', img: President },
  executives: [
    { title: 'Vice-President', name: 'Mr. XYZ Patel', img: President },
    { title: 'Secretary', name: 'Mr. XYZ Patel', img: President },
    { title: 'Treasurer', name: 'Mr. XYZ Patel', img: member },
  ],
  members: Array(8).fill({
    title: 'Member',
    name: 'Mr. XYZabc Patel',
    img: member,
  }),
};

export default function CommitteeTree() {
  return (
    <section className="py-12 px-4 max-w-6xl mx-auto text-center">
      <h2 className="text-3xl font-bold mb-10">Our Committee</h2>

      {/* President */}
      <div className="relative flex flex-col items-center mb-10">
        <MemberCard {...hierarchy.president} />
        <div className="w-1 h-8 bg-gray-400"></div>
      </div>

      {/* Executives */}
      <div className="relative mb-10">
        <div className="flex justify-center gap-8 items-start relative">
          {hierarchy.executives.map((exec, i) => (
            <div key={i} className="flex flex-col items-center">
              <MemberCard {...exec} />
            </div>
          ))}
        </div>

        {/* Connecting line */}
        <div className="absolute top-16 left-1/2 transform -translate-x-1/2 w-3/4 h-0.5 bg-gray-400"></div>
      </div>

      {/* Members */}
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-6 mt-6">
        {hierarchy.members.map((mem, i) => (
          <MemberCard key={i} {...mem} />
        ))}
      </div>
    </section>
  );
}

function MemberCard({ img, title, name }) {
  return (
    <div className="bg-white p-4 border rounded shadow text-center w-32 mx-auto">
      <img src={img} alt={title} className="w-16 h-16 mx-auto rounded-full mb-2" />
      <div className="font-semibold text-sm">{title}</div>
      <div className="text-xs text-gray-600">{name}</div>
    </div>
  );
}
